{
  "schemaVersion": "0.2",
  "slug": "list",
  "name": "List",
  "status": "experimental",
  "purpose": "Renders a group of related items as a list.",
  "scenarios": [
    "Show a bullet list",
    "Show a numbered list",
    "Render a plain list of items"
  ],
  "props": {
    "items": {
      "type": "string",
      "required": true,
      "description": "Array of item strings."
    },
    "variant": {
      "type": "enum",
      "required": false,
      "description": "List marker style.",
      "values": [
        "unordered",
        "ordered",
        "none"
      ],
      "default": "unordered"
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "variant",
      "values": [
        "unordered",
        "ordered",
        "none"
      ],
      "default": "unordered",
      "description": "List marker style."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "List rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "text",
      "page",
      "card"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use lists for layout.",
    "Do not mix ordered and unordered semantics without reason."
  ],
  "a11y": {
    "role": "list",
    "keyboard": [],
    "focus": "Not focusable.",
    "labeling": "Not a labelled region.",
    "wcag": [
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Block list.",
    "breakpoints": {
      "compact": "Block.",
      "medium": "Block.",
      "large": "Block."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only; markers follow list semantics.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "list",
    "states": [
      "unordered",
      "ordered",
      "none"
    ],
    "intents": [
      "enumerate-items"
    ]
  }
}

import './styles.css'

export interface ListProps {
  items: string[]
  variant?: 'unordered' | 'ordered' | 'none'
  className?: string
}

export function List({ items, variant = 'unordered', className }: ListProps) {
  const classes = ['cu-list', 'cu-list--' + variant, className].filter(Boolean).join(' ')
  const Tag = variant === 'ordered' ? 'ol' : 'ul'
  return (
    <Tag className={classes} data-ai-role="list" data-ai-intent="enumerate-items" data-ai-state={variant}>
      {items.map((item, index) => <li className="cu-list__item" key={index}>{item}</li>)}
    </Tag>
  )
}

.cu-list {
  margin: 0;
  padding-inline-start: var(--cu-space-3);
  color: var(--cu-color-fg-default);
}

.cu-list--none {
  list-style: none;
  padding-inline-start: 0;
}

.cu-list__item {
  padding-block: calc(var(--cu-space-1) / 2);
}
